const list = ($input.first().json.value || []).filter(m => m.id).sort((a, b) => new Date(a.receivedDateTime) - new Date(b.receivedDateTime));
if (!list.length) return [{ json: { none: true } }];
const idx = [...new Set([0, Math.floor(list.length / 2), list.length - 1])];
return idx.map(i => ({ json: { id: list[i].id, receivedDateTime: list[i].receivedDateTime, subject: list[i].subject, hasAttachments: list[i].hasAttachments, totalNotices: list.length } }));

// For each picked notice: is the client's own text in the e-mail? which links and attachments does it carry?
const picks = $('Pick Three').all().map(i => i.json);
const bodies = $('Get Body').all().map(i => i.json);
const atts = $input.all().map(i => i.json);
const strip = (h) => String(h || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/&#65279;|&#8203;|&zwnj;|&nbsp;/gi, ' ').replace(/[\u200b-\u200f\u2060\ufeff\u034f]/g, ' ')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|h\d|li)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const out = picks.map((p, i) => {
  if (p.none) return { found: 0, problem: 'no notices found' };
  const b = bodies[i] || {}; const html = (b.body && b.body.content) || '';
  const links = [...new Set([...html.matchAll(/href="([^"]+)"/gi)].map(m => m[1].replace(/&amp;/g, '&')))].filter(u => !/unsubscribe|facebook|instagram|twitter|pinterest|apps\.apple|play\.google/i.test(u)).map(u => u.slice(0, 110));
  const imgs = [...new Set([...html.matchAll(/<img[^>]+src="([^"]+)"/gi)].map(m => m[1]))].filter(u => !/1x1|pixel|track|spacer/i.test(u)).map(u => u.slice(0, 110));
  const a = atts[i] || {};
  return { notice: p.subject, received: p.receivedDateTime, totalNoticesForClient: p.totalNotices, bodyType: b.body && b.body.contentType, htmlLength: html.length,
    bodyPreview: b.bodyPreview, cleanedText: strip(html).slice(0, 1200), links: links.slice(0, 12), images: imgs.slice(0, 8),
    attachments: (a.value || []).map(x => ({ name: x.name, type: x.contentType, size: x.size, inline: x.isInline })), attachmentError: a.error ? JSON.stringify(a.error).slice(0, 120) : undefined };
});
return [{ json: { samples: out } }];
